      testId,
      scriptConfig: /* HTML */ `<script type="module">
        import { init, track } from '/tracker/js/npm_package/plausible.js'
        window.init = init
        window.track = track
        init(
          ${JSON.stringify({
            domain: 'example.com',
            endpoint: `https://plausible.io/api/event`,
            captureOnLocalhost: true
          })}
        )
      </script>`,
      bodyContent: ''
