    expect(result).toEqual({
      data: {
        attempts: 1,
        completed: true,
        trackerIsInHtml: false,
        plausibleIsInitialized: true,
        plausibleIsOnWindow: true,
        disallowedByCsp: false,
        plausibleVersion: version,
        plausibleVariant: 'npm',
        testEvent: {
          callbackResult: { status: 202 },
          requestUrl: 'https://plausible.io/api/event',
          normalizedBody: {
            domain: 'example.com',
            name: 'verification-agent-test',
            version
          },
          responseStatus: 202,
          error: undefined
        },
        cookiesConsentResult: incompleteCookiesConsentResult
      }
    })
  })

  test('using <script type="module"> tag and endpoint: "/events"', async ({
    page
  }, { testId }) => {
    await mockManyRequests({
      page,
      path: `${LOCAL_SERVER_ADDR}/events`,
      awaitedRequestCount: 1,
      fulfill: {
        status: 202,
        contentType: 'text/plain',
        body: 'ok'
      }
    })

    const { url } = await initializePageDynamically(page, {
      testId,
      scriptConfig: /* HTML */ `<script type="module">
        import { init, track } from '/tracker/js/npm_package/plausible.js'
        window.init = init
        window.track = track
        init(
          ${JSON.stringify({
            domain: 'example.com',
            endpoint: `/events`,
            captureOnLocalhost: true
          })}
        )
      </script>`,
      bodyContent: ''
    })

    const response = await page.goto(url)
    const responseHeaders = response?.headers() ?? {}

    const result = await executeVerifier(page, {
      ...DEFAULT_VERIFICATION_OPTIONS,
      responseHeaders
    })

    expect(result).toEqual({
      data: {
        attempts: 1,
        completed: true,
        trackerIsInHtml: false,
        plausibleIsInitialized: true,
        plausibleIsOnWindow: true,
        disallowedByCsp: false,
        plausibleVersion: version,
        plausibleVariant: 'npm',
        testEvent: {
          callbackResult: { status: 202 },
          requestUrl: '/events',
          normalizedBody: {
            domain: 'example.com',
            name: 'verification-agent-test',
            version
          },
          responseStatus: 202,
          error: undefined
        },
        cookiesConsentResult: incompleteCookiesConsentResult
      }
    })
  })

  test('using <script type="module"> tag and endpoint: "https://example.com/events"', async ({
    page
  }, { testId }) => {
    const { url } = await initializePageDynamically(page, {
      testId,
      scriptConfig: /* HTML */ `<script type="module">
        import { init, track } from '/tracker/js/npm_package/plausible.js'
        window.init = init
        window.track = track
        init(
          ${JSON.stringify({
            domain: 'example.com',
            endpoint: `https://example.com/events`,
            captureOnLocalhost: true
          })}
        )
      </script>`,
      bodyContent: ''
