import { test, expect } from '@playwright/test'
import { checkDisallowedByCSP } from '../../installation_support/check-disallowed-by-csp'

const HOST_TO_CHECK = 'plausible.io'

test.describe('checkDisallowedByCSP', () => {
  test('returns false if no CSP header', () => {
    expect(checkDisallowedByCSP({}, HOST_TO_CHECK)).toBe(false)
    expect(checkDisallowedByCSP({ foo: 'bar' }, HOST_TO_CHECK)).toBe(false)
  })

  test('returns false if CSP header is empty', () => {
    expect(
      checkDisallowedByCSP({ 'content-security-policy': '' }, HOST_TO_CHECK)
    ).toBe(false)
  })

  test('returns true if plausible.io is not allowed', () => {
    const headers = {
      'content-security-policy': "default-src 'self' foo.local; example.com"
    }
    expect(checkDisallowedByCSP(headers, HOST_TO_CHECK)).toBe(true)
  })

  test('returns false if plausible.io is allowed', () => {
    const headers = {
      'content-security-policy': "default-src 'self' plausible.io; example.com"
    }
    expect(checkDisallowedByCSP(headers, HOST_TO_CHECK)).toBe(false)
  })

  test('returns false if plausible.io subdomain is allowed', () => {
    const headers = {
      'content-security-policy':
        "default-src 'self' staging.plausible.io; example.com"
    }
    expect(checkDisallowedByCSP(headers, HOST_TO_CHECK)).toBe(false)
  })

  test('returns false if plausible.io is allowed with https', () => {
    const headers = {
      'content-security-policy':
        "default-src 'self' https://plausible.io; example.com"
    }
    expect(checkDisallowedByCSP(headers, HOST_TO_CHECK)).toBe(false)
  })

  test('returns true if plausible.io is not present in any directive', () => {
    const headers = {
      'content-security-policy': "default-src 'self' foo.com; bar.com"
    }
    expect(checkDisallowedByCSP(headers, HOST_TO_CHECK)).toBe(true)
  })
})

import { test, expect } from '@playwright/test'
import {
  checkWordPress,
  WORDPRESS_PLUGIN_VERSION_SELECTOR
} from '../../installation_support/check-wordpress'

function mockDocument(html, hasMetaTag) {
  return {
    documentElement: { outerHTML: `<html>${html}</html>` },
    querySelector: (selector) => {
      if (selector === WORDPRESS_PLUGIN_VERSION_SELECTOR) {
        return hasMetaTag ? {} : null
      }
      return null
    }
  }
}

test.describe('checkWordPress (wordpressPlugin, wordPressLikely)', () => {
  test('handles document undefined', () => {
    const result = checkWordPress(undefined)

    expect(result.wordpressPlugin).toBe(false)
    expect(result.wordpressLikely).toBe(false)
  })

  test('handles document.querySelector undefined', () => {
    const document = { documentElement: { outerHTML: '<html></html>' } }
    const result = checkWordPress(document)

    expect(result.wordpressPlugin).toBe(false)
    expect(result.wordpressLikely).toBe(false)
  })

  test('handles document.documentElement undefined', () => {
    const document = { documentElement: undefined, querySelector: (_) => null }
    const result = checkWordPress(document)

    expect(result.wordpressPlugin).toBe(false)
    expect(result.wordpressLikely).toBe(false)
  })

  test('both false when no WordPress indicators present', () => {
    const document = mockDocument('<head></head><body></body>', false)
    const result = checkWordPress(document)

    expect(result.wordpressPlugin).toBe(false)
    expect(result.wordpressLikely).toBe(false)
  })

  test('both true if WordPress plugin version meta tag detected', () => {
    const document = mockDocument('<head></head><body></body>', true)
    const result = checkWordPress(document)

    expect(result.wordpressPlugin).toBe(true)
    expect(result.wordpressLikely).toBe(true)
  })

  test('detects wordpressLikely by wp-content signature', () => {
    const document = mockDocument(
      '<head><script src="/wp-content/themes/mytheme/script.js"></script></head>',
      false
    )
    const result = checkWordPress(document)

    expect(result.wordpressPlugin).toBe(false)
    expect(result.wordpressLikely).toBe(true)
  })

  test('detects wordpressLikely by wp-includes signature', () => {
    const document = mockDocument(
      '<head><link rel="stylesheet" href="/wp-includes/css/style.css"></head>',
      false
    )
    const result = checkWordPress(document)

    expect(result.wordpressPlugin).toBe(false)
    expect(result.wordpressLikely).toBe(true)
  })

  test('detects wordpressLikely by wp-json signature', () => {
    const document = mockDocument(
      '<body><script>fetch("/wp-json/wp/v2/posts")</script></body>',
      false
    )
    const result = checkWordPress(document)

    expect(result.wordpressPlugin).toBe(false)
    expect(result.wordpressLikely).toBe(true)
  })

  test('detects wordpressLikely by multiple signatures', () => {
    const document = mockDocument(
      `
        <head>
          <script src="/wp-content/themes/mytheme/script.js"></script>
        </head>
        <body>
          <script>fetch("/wp-json/wp/v2/posts")</script>
        </body>
      `,
      false
    )

    const result = checkWordPress(document)

    expect(result.wordpressPlugin).toBe(false)
    expect(result.wordpressLikely).toBe(true)
  })
})

import { compileFile } from '../../compiler/index.js'
import variantsFile from '../../compiler/variants.json' with { type: 'json' }
import { Page } from '@playwright/test'
import { VerifierArgs, VerifierResult } from './types'

const VERIFIER_JS_VARIANT = variantsFile.manualVariants.find(
  (variant) => variant.name === 'verifier.js'
)
const DETECTOR_JS_VARIANT = variantsFile.manualVariants.find(
  (variant) => variant.name === 'detector.js'
)

export async function executeVerifier(
  page: Page,
  {
    responseHeaders,
    maxAttempts,
    timeoutBetweenAttemptsMs,
    ...functionContext
  }: VerifierArgs & { maxAttempts: number; timeoutBetweenAttemptsMs: number }
): Promise<VerifierResult> {
  const verifierCode = (await compileFile(VERIFIER_JS_VARIANT, {
    returnCode: true
  })) as string

  try {
    async function verify() {
      await page.evaluate(verifierCode) // injects window.verifyPlausibleInstallation
      return await page.evaluate(
        // @ts-expect-error - window.verifyPlausibleInstallation has been injected
        (c) => {
          return window.verifyPlausibleInstallation(c)
        },
        { ...functionContext, responseHeaders }
      )
    }

    let lastError
    for (let attempts = 1; attempts <= maxAttempts; attempts++) {
      try {
        const output = await verify()
        return {
          data: {
            ...output.data,
            attempts
          }
        }
      } catch (error) {
        lastError = error
        if (
          typeof error?.message === 'string' &&
          error.message.toLowerCase().includes('execution context')
        ) {
          await new Promise((resolve) =>
            setTimeout(resolve, timeoutBetweenAttemptsMs)
          )
          continue
        }
        throw error
      }
    }
    throw lastError
  } catch (error) {
    return {
      data: {
        completed: false,
        error: {
          message: error?.message ?? JSON.stringify(error)
        }
      }
    }
  }
}

export async function detect(page, context) {
  const { url, detectV1, timeoutMs } = context
  const debug = context.debug ? true : false

  const detectorCode = await compileFile(DETECTOR_JS_VARIANT, {
    returnCode: true
  })

  await page.goto(url)
  await page.evaluate(detectorCode)

  return await page.evaluate(
    async (d) => {
      // @ts-expect-error - window.scanPageBeforePlausibleInstallation has been injected
      return await window.scanPageBeforePlausibleInstallation(d)
    },
    { detectV1, debug, timeoutMs }
  )
}

defmodule Plausible.InstallationSupport.CheckTest do
  use Plausible.DataCase, async: true

  @moduletag :ee_only

  on_ee do
    import ExUnit.CaptureLog
    import Plausible.AssertMatches
    alias Plausible.InstallationSupport.{State, Verification}

    @moduletag :capture_log

    test "a check that raises" do
      defmodule FaultyCheckRaise do
        use Plausible.InstallationSupport.Check

        @impl true
        def report_progress_as, do: "Faulty check"

        @impl true
        def perform(_, _), do: raise("boom")
      end

      state = %State{
        url: "https://example.com",
        report_to: self(),
        diagnostics: %Verification.Diagnostics{}
      }

      {result, log} =
        with_log(fn ->
          FaultyCheckRaise.perform_safe(state, [])
        end)

      assert log =~
               ~s|Error running check Plausible.InstallationSupport.CheckTest.FaultyCheckRaise on https://example.com: %RuntimeError{message: "boom"}|

      assert_matches %Verification.Diagnostics{
                       service_error: %{
                         code: :internal_check_error,
                         extra: %RuntimeError{message: "boom"}
                       }
                     } =
                       result.diagnostics
    end

    test "a check that throws" do
      defmodule FaultyCheckThrow do
        use Plausible.InstallationSupport.Check

        @impl true
        def report_progress_as, do: "Faulty check"

        @impl true
        def perform(_, _), do: :erlang.throw(:boom)
      end

      state = %State{
        url: "https://example.com",
        report_to: self(),
        diagnostics: %Verification.Diagnostics{}
      }

      {result, log} =
        with_log(fn ->
          FaultyCheckThrow.perform_safe(state, [])
        end)

      assert log =~
               ~s|Error running check Plausible.InstallationSupport.CheckTest.FaultyCheckThrow on https://example.com: :boom|

      assert_matches %Verification.Diagnostics{
                       service_error: %{code: :internal_check_error, extra: :boom}
                     } = result.diagnostics
    end

    test "a check that times out" do
      defmodule FaultyCheckTimeout do
        use Plausible.InstallationSupport.Check

        @impl true
        def report_progress_as, do: "Faulty check"

        @impl true
        def perform(_, _), do: :timer.sleep(500)
      end

      state = %State{
        url: "https://example.com",
        report_to: self(),
        diagnostics: %Verification.Diagnostics{}
      }

      result = FaultyCheckTimeout.perform_safe(state, timeout: 100)

      assert_matches %Verification.Diagnostics{
                       service_error: %{
                         code: :internal_check_timeout,
                         extra: "FaultyCheckTimeout timed out after 100ms"
                       }
                     } = result.diagnostics
    end
  end
end
